Since Next.js components are isolated, you cannot rely on `useState` inside a single component to track the state of *all* tooltips. Instead, you must lift the state up to a Context that wraps your entire application (or the specific layout where the tooltips live).

Here is a complete, copy-pasteable solution using **React Context** and **Tailwind CSS** (standard in Next.js).

### 1. Create the Context and Provider

First, create a file to manage the global state. This will hold the `activeTooltipId` and the `setActiveTooltipId` function.

**File:** `context/TooltipContext.tsx`

```tsx
'use client';

import React, { createContext, useContext, useState, ReactNode } from 'react';

// Define the shape of our context
interface TooltipContextType {
  activeTooltipId: string | null;
  setActiveTooltipId: (id: string | null) => void;
}

const TooltipContext = createContext<TooltipContextType | undefined>(undefined);

interface TooltipProviderProps {
  children: ReactNode;
}

export function TooltipProvider({ children }: TooltipProviderProps) {
  const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);

  return (
    <TooltipContext.Provider value={{ activeTooltipId, setActiveTooltipId }}>
      {children}
    </TooltipContext.Provider>
  );
}

export function useTooltip() {
  const context = useContext(TooltipContext);
  if (!context) {
    throw new Error('useTooltip must be used within a TooltipProvider');
  }
  return context;
}
```

