Here is a reusable React component that implements the `Layout` with the requested `variant` prop. It uses Tailwind CSS to handle the styling logic dynamically.

```jsx
import React from 'react';

const Layout = ({ children, variant = 'centered' }) => {
  // Determine the base classes based on the variant
  const baseClasses = "p-4"; // Padding for content

  let containerClasses = "";

  if (variant === 'full-width') {
    containerClasses = "w-full";
  } else if (variant === 'centered') {
    containerClasses = "max-w-[1000px] mx-auto";
  } else {
    // Fallback to centered if an invalid variant is passed
    containerClasses = "max-w-[1000px] mx-auto";
  }

  return (
    <div className={containerClasses}>
      <div className={baseClasses}>
        {children}
      </div>
    </div>
  );
};

export default Layout;

