### How it works
1.  **DNS Server**: It uses the `net/http` package to listen on port 53 (or a custom port).
2.  **Resolver**: It uses the `net` package to perform the actual DNS lookup against Google (8.8.8.8) and Cloudflare (1.1.1.1).
3.  **Caching**: It uses a `sync.Map` to store the results. This is thread-safe and efficient for concurrent lookups.
4.  **Concurrency**: It uses `sync.Once` to ensure the DNS lookup for a specific hostname only happens once, even if multiple clients ask for it simultaneously.

### The Code (`dns_forwarder.go`)

```go
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net"
	"net/http"
	"sync"
	"time"
)

// CacheEntry stores the resolved IP and the time it was resolved
type CacheEntry struct {
	IP       string
	ResolvedAt time.Time
}

// Global cache map
var (
	dnsCache = sync.Map{}
)

// resolveHost attempts to resolve a hostname using Google and Cloudflare DNS
func resolveHost(host string) (string, error) {
	// List of upstream DNS servers
	dnsServers := []string{"8.8.8.8", "1.1.1.1"}

	// Try each server until one succeeds
	for _, server := range dnsServers {
		// Create a resolver pointing to the specific upstream server
		resolver := &net.Resolver{
			PreferGo: true,
			Dial: func(ctx context.Context, network, address string) (net.Conn, error) {
				dialer := &net.Dialer{
					Timeout:   3 * time.Second,
					KeepAlive: 30 * time.Second,
				}
				return dialer.DialContext(ctx, "udp", address)
			},
		}

		ips, err := resolver.LookupIPAddr(host)
		if err == nil && len(ips) > 0 {
			return ips[0].IP.String(), nil
		}
	}

	return "", fmt.Errorf("failed to resolve %s", host)
}

