Here are the two functions to pack and unpack the data.

### The Logic

1.  **Packing**: We iterate through the entities. For each entity, we take the `id` (4 bits) and `size` (3 bits), combine them into a single 7-bit integer, and write that integer into the `Uint8Array` at the current offset. We then advance the offset by 1 byte.
2.  **Unpacking**: We iterate through the `Uint8Array`. For each byte, we extract the lower 4 bits as the `id` and the upper 3 bits as the `size`.

### The Code

```javascript
/**
 * Packs an array of entities into a Uint8Array.
 * 
 * @param {Array} entities - Array of objects with { id, size }
 * @returns {Uint8Array} - The packed buffer
 */
function packEntities(entities) {
    if (!Array.isArray(entities)) {
        throw new Error("Input must be an array");
    }

    // Calculate total size: 1 byte per entity (4 bits + 3 bits = 7 bits < 8 bits)
    const totalSize = entities.length;
    const buffer = new Uint8Array(totalSize);
    let offset = 0;

    for (const entity of entities) {
        // Validate input
        if (typeof entity.id !== 'number' || typeof entity.size !== 'number') {
            throw new Error("Entity must have numeric 'id' and 'size' properties");
        }

        // Masking logic:
        // 1. Shift 'size' (3 bits) to the left by 4 positions.
        // 2. OR it with 'id' (4 bits).
        // 3. Mask with 0xFF (255) to ensure it fits in 1 byte.
        const packedValue = ((entity.size << 4) | entity.id) & 0xFF;

        buffer[offset] = packedValue;
        offset++;
    }

    return buffer;
}

/**
 * Unpacks a Uint8Array into an array of entities.
 * 
 * @param {Uint8Array} buffer - The packed buffer
 * @returns {Array} - Array of objects with { id, size }
 */
function unpackEntities(buffer) {
    if (!(buffer instanceof Uint8Array)) {
        throw new Error("Input must be a Uint8Array");
    }

    const entities = [];
    // Iterate through every byte in the buffer
    for (let i = 0; i < buffer.length; i++) {
        const byte = buffer[i];

        // Extracting logic:
        // 1. Shift right by 4 to get 'size' (upper 3 bits).
        // 2. Mask with 0x07 (binary 00000111) to keep only the lower 3 bits.
        const size = (byte >> 4) & 0x07;

        // 3. Mask with 0x0F (binary 00001111) to keep only the lower 4 bits.
        const id = byte & 0x0F;

        entities.push({ id, size });
    }

    return entities;
}

